import {SEEDS,loadSeed,updateAnswer,proposeUpdate,changeRows} from './seeds.js';
import {renderJourney,mountJourneyMap,destroyJourneyMap} from './viewer.js';
import {COVERAGE,getNextQuestion,proposeMoments,extractTrainingMetrics,isStoryAnswer} from './interview.js';
import {createExample} from './examples.js';
import {renderTraining} from './charts.js';
import {saveProject,loadProject,listProjects,deleteProject} from './storage.js';

const app=document.querySelector('#app');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const activityLabel=value=>({cycling:'Cycling',running:'Running',hiking:'Hiking',walking:'Walking'}[value]||'Activity');
const safeImage=value=>typeof value==='string'&&(/^data:image\/(png|jpeg|webp|gif|avif);base64,/i.test(value)||/^(?:\.\/)?(?:stp\/)?assets\/[a-zA-Z0-9._/-]+$/.test(value))?value:'';
let selectedMoment='overview';
let project=null,screen='home',saveState='Saved in this browser',error='',busy=false,noticeTimer,editSaveTimer=null,saveQueue=Promise.resolve();
function notify(message,isError=false){const n=document.querySelector('#notice');n.textContent=message;n.classList.toggle('error',isError);n.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.hidden=true,isError?10000:4500);}
function updateSaveLabel(){document.querySelectorAll('[data-save-status]').forEach(el=>el.textContent=saveState);}
async function persist(){
 if(!project)return false;
 const snapshot=structuredClone(project);saveState='Saving…';updateSaveLabel();
 const attempt=saveQueue.catch(()=>{}).then(()=>saveProject(snapshot));saveQueue=attempt;
 try{await attempt;saveState='Saved in this browser';updateSaveLabel();return true;}catch(e){saveState='Not saved · export a copy';error=e.message;updateSaveLabel();notify(e.message,true);return false;}
}
function dirty(){project.revision=(project.revision||1)+1;project.finalApproved=false;}
function projectNotice(){return `<p class="small-note">${project.sample?'Synthetic example · ':''}Simulated interview · saved in this browser</p>`;}
function progressSteps(){const steps=[['interview','Interview'],['review','Moments'],['media','Photos'],['preview','Your story']];return `<nav class="steps" aria-label="Story creation steps">${steps.map(([stage,label],i)=>`<button class="step ${screen===stage?'active':''}" data-action="stage" data-stage="${stage}" ${(stage!=='interview'&&!project.moments?.length)||(['media','preview'].includes(stage)&&(project.needsRegeneration||project.moments.some(m=>!m.approved)))?'disabled':''} ${screen===stage?'aria-current="step"':''}><span>${i+1}</span>${label}</button>`).join('')}</nav>`;}
function seedBanner(){return project.seedKey?`<details class="seed-banner"><summary>Your editable ${project.seedKey==='alex'?'Alex':'first-5K'} copy · original seed stays unchanged</summary>${(project.seedNotes||[]).map(n=>`<p>${esc(n)}</p>`).join('')}<p>Starting moments are provided for exploration, not approved on your behalf. Edits require review. Start a fresh copy at any time; this copy remains saved.</p><button class="text-button" data-action="seed" data-seed="${esc(project.seedKey)}" data-stage="interview">Start a fresh copy ↗</button></details>`:'';}
function interviewEditor(){return `<section class="panel interview-editor"><p class="eyebrow">${project.seedKey?'Prefilled walkthrough':'Your interview'}</p><h2>Make the inputs yours.</h2><p>Change any answer, or keep it. Original source answers remain available when you review changes. Conversation-only replies are retained but do not become story text.</p><div class="form-grid">${[['name','Name'],['event','Event or accomplishment'],['date','Date'],['why','Why you want to remember it']].map(([key,label])=>`<div class="field"><label for="project-${key}">${label}</label><input id="project-${key}" data-project-edit="${key}" value="${esc(project[key]||'')}" maxlength="${key==='why'?2000:150}" ${key==='date'?'type="date"':''}></div>`).join('')}<div class="field"><label for="project-activity">Activity</label><select id="project-activity" data-project-edit="activity">${['cycling','running','hiking','walking'].map(a=>`<option value="${a}" ${project.activity===a?'selected':''}>${esc(activityLabel(a))}</option>`).join('')}</select></div></div><div class="answer-edit-list">${COVERAGE.map(c=>{const turns=project.turns.filter(t=>t.questionId.split('.followup.')[0]===c.id);return `<details class="interview-topic" ${c.id==='summary'?'open':''}><summary>${esc(c.label)} <span>${turns.length} ${turns.length===1?'answer':'answers'}</span></summary>${turns.map(t=>{const i=project.turns.indexOf(t);return `<section class="answer-edit"><label class="field-label" for="answer-${esc(t.id)}">${i+1}. ${esc(t.question)}</label><textarea id="answer-${esc(t.id)}" data-answer-edit="${esc(t.id)}" maxlength="8000">${esc(t.answer)}</textarea><label class="answer-use"><input type="checkbox" data-answer-use="${esc(t.id)}" ${isStoryAnswer(t)?'checked':''}> Use this answer in the story</label>${project.sourceChanges?.[t.id]?`<details><summary>Before your edit</summary><p>${esc(project.sourceChanges[t.id].answer)}</p></details>`:''}</section>`;}).join('')}</details>`;}).join('')}</div><div class="bottom-actions"><button class="text-button" data-action="stage" data-stage="review">Review current moments</button><button class="button" data-action="generate">${project.needsRegeneration?'Review proposed changes':'Review moments'} ↗</button></div></section>`;}
function pendingChanges(){const rows=changeRows(project.moments,project.pendingMomentUpdate);return `<section class="panel"><p class="eyebrow">Before applying anything</p><h2>Review what would change.</h2><p>Your current story is still saved. Changed answers produce verbatim drafts in mock mode; untouched moments keep their reviewed wording, photos, and order.</p>${rows.length?rows.map(r=>`<article class="change-row"><h3>${esc(r.after?.title||r.before?.title)}</h3><div class="change-columns"><div><strong>Current story</strong><p>${esc(r.before?.text||'New moment')}</p></div><div><strong>Proposed draft</strong><p>${esc(r.after?.text||'Removed: no story answer remains')}</p></div></div></article>`).join(''):'<p>No story wording changes are needed. Applying clears the pending interview update.</p>'}<div class="bottom-actions"><button class="text-button" data-action="cancel-update">Keep current story for now</button><button class="button" data-action="apply-update">Apply these drafts ↗</button></div></section>`;}
function shell(content){return `<div class="workspace"><div class="project-bar"><div><h1>${esc(project.event||'Your experience')}</h1>${projectNotice()}</div><div class="project-actions"><span class="saved-status" data-save-status>${esc(saveState)}</span><button class="text-button" data-action="export">Export copy ↗</button><button class="text-button" data-action="home">All stories</button></div></div>${progressSteps()}${seedBanner()}${error?`<div class="error-inline">${esc(error)} <button class="text-button" data-action="retry-save">Retry saving</button></div>`:''}${content}</div>`;}
async function render({focus=false}={}){
 destroyJourneyMap();document.body.classList.toggle('viewing',screen==='preview'&&!!project);
 if(screen==='home'){await renderHome();return;}
 if(screen==='setup'){renderSetup();return;}
 if(!project){screen='home';await renderHome();return;}
 if(screen==='interview')renderInterview();
 if(screen==='review')renderReview();
 if(screen==='media')renderMedia();
 if(screen==='preview')renderPreview();
 if(focus){window.scrollTo({top:0,behavior:'instant'});app.focus({preventScroll:true});}
}
async function renderHome(){
 let saved=[];try{saved=await listProjects();}catch(e){error=e.message;}
 app.innerHTML=`<div class="home"><section class="hero"><div class="hero-copy"><p class="eyebrow">An athlete’s story, with the people who were there</p><h1>Back in the saddle.<br><em>Friends at the finish.</em></h1><p>Explore Alex’s Seattle to Portland ride: twenty weeks of training, a long day on the bike, and the friends waiting to take him home.</p><div class="hero-actions"><a class="button" href="./stp/">Explore Alex’s story ↗</a><button class="button secondary" data-action="new">Create your story ↗</button></div><p class="small-note">Alex’s story is a curated fictional example. Create your own with a simulated interview, your photos, and this visual story format.</p></div><a class="hero-real" href="./stp/" aria-label="Explore Alex’s visual story"><img src="./stp/assets/seq-photo-10.png" alt="Illustration of friends celebrating Alex’s ride"><span>STP 2026 · Alex’s journey ↗</span></a></section><div class="process-strip"><div><span class="process-num">01</span>Talk it through</div><div><span class="process-num">02</span>Choose your moments</div><div><span class="process-num">03</span>Add your photos</div><div><span class="process-num">04</span>Keep your story</div></div><section><div class="section-heading"><h2>Try a seeded walkthrough</h2><span class="small-note">Every start creates your own editable copy</span></div><div class="sample-grid">${SEEDS.map(seed=>`<section class="seed-card"><p class="eyebrow">${seed.id==='alex'?'Full story · photos · training':'Interview · no photos yet'}</p><h3>${esc(seed.title)}</h3><p>${esc(seed.description)}</p><div class="seed-entry">${[['interview','Interview'],['review','Review moments'],['media','Photos'],['preview','Preview']].map(([stage,label])=>`<button class="button small secondary" data-action="seed" data-seed="${seed.id}" data-stage="${stage}">${label}</button>`).join('')}</div></section>`).join('')}</div></section><section><div class="section-heading"><h2>Your saved stories</h2><span class="small-note">Only on this device and browser</span></div>${error?`<p class="error-inline">${esc(error)}</p>`:''}${saved.length?`<div class="saved-list">${saved.map(p=>`<div class="saved-item"><div><strong>${esc(p.event)}</strong><p>${esc(p.name)} · ${p.finalApproved?'Final version approved':`${p.moments?.length||0} moments · draft`}${p.sample?' · example':''}</p></div><button class="button small secondary" data-action="resume" data-id="${esc(p.id)}">Open ↗</button><button class="text-button" data-action="delete-project" data-id="${esc(p.id)}" aria-label="Delete ${esc(p.event)}">Delete</button></div>`).join('')}</div>`:'<div class="empty">Your first story starts with a conversation. No activity tracker required.</div>'}</section><p class="home-footer">A prototype for athlete-led storytelling. <button class="text-button" data-action="about">What is real, and what is simulated?</button></p></div>`;
}
function renderSetup(){app.innerHTML=`<div class="setup"><button class="text-button" data-action="home">← Back</button><p class="eyebrow" style="margin-top:28px">A little context to begin</p><h1>What would you like<br>to remember?</h1><p class="muted">A race, a hike, a personal milestone. You decide what counts.</p><form id="setup-form" class="panel"><div class="form-grid"><div class="field"><label for="name">Your name</label><input id="name" name="name" autocomplete="given-name" maxlength="80" placeholder="What should we call you?" required></div><div class="field"><label for="activity">Activity</label><select id="activity" name="activity"><option value="cycling">Cycling</option><option value="running">Running</option><option value="hiking">Hiking</option><option value="walking">Walking</option></select></div><div class="field full"><label for="event">Event or accomplishment</label><input id="event" name="event" maxlength="150" placeholder="e.g. My first century ride" required></div><div class="field"><label for="date">When was it? <span class="muted">(optional)</span></label><input type="date" id="date" name="date"></div><div class="field full"><label for="why">What makes you want to remember it? <span class="muted">(optional)</span></label><textarea id="why" name="why" maxlength="2000" placeholder="A sentence is plenty to get started."></textarea></div></div><div class="form-actions"><p class="small-note" style="margin:0;max-width:270px">This is a simulated interview. Your answers and photos stay in this browser.</p><button class="button" type="submit">Begin interview ↗</button></div></form></div>`;}
function renderInterview(){
 if(project.seedKey||project.editInterview){app.innerHTML=shell(interviewEditor());return;}
 const q=getNextQuestion(project);
 if(!q){app.innerHTML=shell(`<section class="panel"><p class="eyebrow">You have covered the experience</p><h2>Ready to look at your moments?</h2><p class="muted">We will organize your answers into a draft. You can edit the wording and decide what to keep.</p><button class="button" data-action="generate">Review my moments ↗</button><details class="previous-answers"><summary>Read your ${project.turns.length} answers</summary>${answersHTML()}</details></section>`);return;}
 const completed=new Set(project.turns.map(t=>t.questionId.split('.followup.')[0]));
 const currentIndex=COVERAGE.findIndex(c=>c.id===q.coverageId||c.id===q.id);
 app.innerHTML=shell(`<div class="interview-layout"><aside class="coverage-sidebar"><p class="eyebrow">The conversation</p><ol class="coverage-list">${COVERAGE.map((c,i)=>`<li class="${c.id===q.coverageId?'current':completed.has(c.id)?'done':''}"><span class="coverage-dot">${completed.has(c.id)?'✓':String(i+1).padStart(2,'0')}</span>${esc(c.label)}</li>`).join('')}</ol><p class="small-note" style="margin-top:20px">You can skip a question or move to review whenever you are ready.</p></aside><section class="panel interview-card"><div class="interviewer"><span class="interviewer-icon">↗</span>Story interview <span class="badge" style="margin-left:auto;font-size:9px">Simulated</span></div><p class="eyebrow">${esc(COVERAGE.find(c=>c.id===q.coverageId)?.label||'A little more about that')}</p><h2>${esc(q.text)}</h2><form id="answer-form" data-question-id="${esc(q.id)}" data-question="${esc(q.text)}"><label class="field-label" for="answer">Your answer</label><textarea class="answer-box" id="answer" name="answer" maxlength="8000" placeholder="Tell it however you remember it. A few sentences is fine." style="margin-top:9px" required></textarea><div class="question-meta"><span>${currentIndex>=0?`Topic ${currentIndex+1} of ${COVERAGE.length}`:`${project.turns.length} answers saved`}</span><span id="character-count">0 / 8,000</span></div><div class="interview-actions"><div style="display:flex;gap:17px"><button class="text-button" type="button" data-action="skip">Skip this question</button><button class="text-button" type="button" data-action="generate" ${project.turns.some(t=>t.answer.trim())?'':'disabled'}>Review now</button></div><button class="button" type="submit">Continue ↗</button></div></form>${project.turns.length?`<details class="previous-answers"><summary>Your earlier answers (${project.turns.length})</summary>${answersHTML()}</details>`:''}</section></div>`);
}
function answersHTML(){return '<button class="text-button" data-action="edit-answers">Edit saved interview answers ↗</button>'+project.turns.map(t=>`<div class="previous-answer"><strong>${esc(t.question)}</strong><p>${esc(t.answer||'Skipped')}</p></div>`).join('');}
function sourceHTML(moment){const turns=moment.sourceTurnIds.map(id=>project.turns.find(t=>t.id===id)).filter(Boolean);return `<details class="source-details"><summary>${moment.edited?'Edited by you · original source: ':'Based on '}${turns.length} ${turns.length===1?'answer':'answers'}</summary>${turns.map(t=>`<blockquote><strong>${esc(t.question)}</strong><br>${esc(t.answer)}</blockquote>`).join('')}${moment.contextEdited?'<p>People and place details entered by you during review.</p>':''}</details>`;}
function metricsForm(){return `<details class="panel metrics-form"><summary>Optional: add your training totals</summary><p>Add figures you remember or have recorded. These create metric cards, not an invented week-by-week history. Leave anything you do not know blank.</p><div class="metric-inputs">${[['preparationWeeks','Preparation (weeks)'],['trainingDays','Training days'],['distanceKm','Distance (km)'],['trainingHours','Time training (hours)']].map(([key,label])=>`<div class="field"><label for="metric-${key}">${label}</label><input id="metric-${key}" type="number" min="0" max="1000000" step="any" data-metric="${key}" value="${Number.isFinite(project.metrics?.[key])?esc(project.metrics[key]):''}" placeholder="Optional"></div>`).join('')}</div><p class="small-note" style="margin-bottom:0">${project.metrics?.source==='synthetic_fixture'?'This example includes synthetic training records. Editing totals changes their label to athlete-reported and removes the sample weekly chart.':'Figures are identified as athlete-reported.'}</p></details>`;}
function momentContextForm(m){return `<details class="moment-context-editor"><summary>Optional: people and place for this moment</summary><p>Use details you know. Locations place numbered pins on your story map. Leave these blank when they do not belong in the story.</p><div class="form-grid"><div class="field"><label for="support-name-${esc(m.id)}">Who was alongside you?</label><input id="support-name-${esc(m.id)}" data-context="supportName" data-id="${esc(m.id)}" value="${esc(m.supportName||'')}" maxlength="150"></div><div class="field"><label for="place-${esc(m.id)}">Place name</label><input id="place-${esc(m.id)}" data-context="locationName" data-id="${esc(m.id)}" value="${esc(m.locationName||'')}" maxlength="200"></div><div class="field full"><label for="support-text-${esc(m.id)}">What was happening with them, and why did it matter to you?</label><textarea id="support-text-${esc(m.id)}" data-context="supportText" data-id="${esc(m.id)}" maxlength="4000">${esc(m.supportText||'')}</textarea></div><div class="field"><label for="lat-${esc(m.id)}">Latitude (optional, −90 to 90)</label><input id="lat-${esc(m.id)}" type="number" min="-90" max="90" step="any" data-context="latitude" data-id="${esc(m.id)}" value="${Number.isFinite(m.latitude)?m.latitude:''}"></div><div class="field"><label for="lng-${esc(m.id)}">Longitude (optional, −180 to 180)</label><input id="lng-${esc(m.id)}" type="number" min="-180" max="180" step="any" data-context="longitude" data-id="${esc(m.id)}" value="${Number.isFinite(m.longitude)?m.longitude:''}"></div></div></details>`;}
function renderReview(){if(project.pendingMomentUpdate){app.innerHTML=shell(pendingChanges());return;}const approved=project.moments.filter(m=>m.approved).length;app.innerHTML=shell(`<div class="review-head"><div><p class="eyebrow">Make the story yours</p><h2>Your moments, for review.</h2><p>These drafts use your answers. Edit anything that does not sound right, then approve the moments you want to keep. Sources are one click away.</p></div><div class="review-tools"><span class="badge">${approved} / ${project.moments.length} ready for preview</span><button class="button small secondary" data-action="approve-all" ${project.moments.length&&!project.needsRegeneration?'':'disabled'}>Approve all</button></div></div>${project.needsRegeneration?`<div class="error-inline"><strong>Your interview has new answers.</strong> These drafts do not include them yet. Rebuild the moments to include the new source material; you will review the replacement drafts before approving them. <button class="button small secondary" data-action="generate">Update moments from interview ↗</button></div>`:''}<div class="moments-list">${project.moments.length?project.moments.map((m,i)=>`<article class="moment-card" data-moment="${esc(m.id)}"><span class="moment-num">${String(i+1).padStart(2,'0')}</span><div><div class="moment-top"><span class="badge ${m.approved?'approved':''}">${m.approved?(m.approvalOrigin==='seed'?'Seed baseline':'✓ Approved'):'Draft · review needed'}</span><div><button class="text-button" data-action="move-up" data-id="${esc(m.id)}" ${i===0?'disabled':''} aria-label="Move ${esc(m.title)} earlier">↑</button><button class="text-button" data-action="move-down" data-id="${esc(m.id)}" ${i===project.moments.length-1?'disabled':''} aria-label="Move ${esc(m.title)} later" style="margin-left:10px">↓</button><button class="text-button" data-action="remove-moment" data-id="${esc(m.id)}" style="margin-left:15px">Remove</button></div></div><label class="field-label" for="title-${esc(m.id)}">Moment heading</label><input class="moment-edit moment-heading-input" id="title-${esc(m.id)}" data-edit="title" data-id="${esc(m.id)}" value="${esc(m.title)}" maxlength="180"><label class="field-label" for="body-${esc(m.id)}">What you want to say</label><textarea class="moment-edit moment-body-input" id="body-${esc(m.id)}" data-edit="text" data-id="${esc(m.id)}" maxlength="8000">${esc(m.text)}</textarea>${momentContextForm(m)}<div class="moment-footer">${sourceHTML(m)}<button class="button small ${m.approved?'secondary':''}" data-action="approve-moment" data-id="${esc(m.id)}" ${m.approved||project.needsRegeneration?'disabled':''}>${m.approved?(m.approvalOrigin==='seed'?'Seed ready':'Approved ✓'):'Approve moment'}</button></div></div></article>`).join(''):'<div class="empty">No moments yet. Answer at least one interview question to create a draft.</div>'}</div>${metricsForm()}<div class="bottom-actions"><button class="text-button" data-action="stage" data-stage="interview">← Return to interview</button><button class="button" data-action="stage" data-stage="media" ${approved&&approved===project.moments.length&&!project.needsRegeneration?'':'disabled'}>Add photos ↗</button></div>${approved!==project.moments.length?'<p class="small-note">Approve or remove each draft before moving on to photos.</p>':''}`);}
function unassignedMedia(){const photos=project.media.filter(a=>!project.moments.some(m=>m.id===a.momentId));return photos.length?`<section class="media-card"><h3>Photos from removed moments</h3><p>These photos are still saved. Choose another moment for each one.</p><div class="media-grid">${photos.map(a=>`<div class="media-thumb"><img src="${esc(safeImage(a.dataUrl))}" alt="${esc(a.filename)}"><label for="unassigned-${esc(a.id)}">Move photo to moment</label><select id="unassigned-${esc(a.id)}" data-tag="${esc(a.id)}"><option value="">Choose a moment</option>${project.moments.map(m=>`<option value="${esc(m.id)}">${esc(m.title)}</option>`).join('')}</select></div>`).join('')}</div></section>`:'';}
function renderMedia(){app.innerHTML=shell(`<div class="review-head"><div><p class="eyebrow">Put yourself back there</p><h2>Add the photos you want to keep.</h2><p>Tag an image to its moment. Photos are optional and stay in this browser. You can add up to 12 images, 8 MB each.</p></div><span class="badge">${project.media.length} / 12 photos</span></div><div class="media-layout">${unassignedMedia()}${project.moments.map((m,i)=>{const media=project.media.filter(x=>x.momentId===m.id);return `<section class="media-card"><div class="media-card-head"><div><p class="eyebrow" style="margin:0 0 7px">Moment ${String(i+1).padStart(2,'0')}</p><h3>${esc(m.title)}</h3></div><label class="file-button">＋ Add photos<input type="file" data-upload="${esc(m.id)}" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" multiple ${project.media.length>=12?'disabled':''}></label></div><p>${esc(m.text.length>150?m.text.slice(0,147)+'…':m.text)}</p>${media.length?`<div class="media-grid">${media.map(asset=>`<div class="media-thumb"><img src="${esc(safeImage(asset.dataUrl))}" alt="${esc(asset.filename)}"><button class="icon-button" data-action="remove-media" data-id="${esc(asset.id)}" aria-label="Remove ${esc(asset.filename)}">✕</button><label class="sr-only" for="tag-${esc(asset.id)}">Move photo to moment</label><select id="tag-${esc(asset.id)}" data-tag="${esc(asset.id)}">${project.moments.map(x=>`<option value="${esc(x.id)}" ${x.id===asset.momentId?'selected':''}>${esc(x.title)}</option>`).join('')}</select><button class="text-button" data-action="overview-photo" data-id="${esc(asset.id)}">Use as overview image</button></div>`).join('')}</div>`:'<div class="no-photo">No photo attached. This moment can stand on your words alone.</div>'}</section>`;}).join('')}</div><div class="bottom-actions"><button class="text-button" data-action="stage" data-stage="review">← Review moments</button><button class="button" data-action="stage" data-stage="preview">Preview your story ↗</button></div>`);}
function renderPreview(){
 const selected=project.moments.filter(m=>m.approved);
 app.innerHTML=`<div class="viewer-workspace"><div class="viewer-controls"><p>${project.sample?'Fictional example · ':''}Simulated interview · <span data-save-status>${esc(saveState)}</span></p><div><button class="text-button" data-action="home">All stories</button><button class="text-button" data-action="stage" data-stage="review">Edit story</button><button class="text-button" data-action="export">Export ↗</button><button class="button small" data-action="final-approve" ${project.finalApproved||!selected.length||project.needsRegeneration||project.moments.some(m=>!m.approved)?'disabled':''}>${project.finalApproved?'Approved ✓':'Approve this version'}</button></div></div>${renderJourney(project,selectedMoment)}</div>`;
 mountJourneyMap(project,selectedMoment,id=>{selectedMoment=id;render();});
}

function formatDate(value){const parts=String(value).split('-');if(parts.length!==3)return value;return new Date(Number(parts[0]),Number(parts[1])-1,Number(parts[2])).toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'});}
function cleanProject(p){p.turns||=[];p.moments||=[];p.media||=[];p.metrics||={};p.revision||=1;return p;}
async function setStage(stage){
 if(stage==='preview')selectedMoment='overview';
 if(['media','preview'].includes(stage)&&(project.needsRegeneration||!project.moments.length||project.moments.some(m=>!m.approved))){notify(project.needsRegeneration?'Update the moments to include your new interview answers first.':'Approve or remove each draft moment first.');screen='review';await render({focus:true});return;}
 screen=stage;project.stage=stage;await persist();await render({focus:true});
}
async function generate(){
 if(!project.turns.some(isStoryAnswer)){notify('Add at least one story answer before reviewing moments.');return;}
 if(project.moments.length){
  if(!project.needsRegeneration){await setStage('review');return;}
  project.pendingMomentUpdate=proposeUpdate(project);await setStage('review');return;
 }
 project.moments=proposeMoments(project);project.needsRegeneration=false;if(!project.metrics?.manuallyEdited&&project.metrics?.source!=='synthetic_fixture')project.metrics=extractTrainingMetrics(project);dirty();await setStage('review');
}

function exportProject(){const blob=new Blob([JSON.stringify({...project,exportedAt:new Date().toISOString(),demoNotice:'Browser-local prototype; simulated interview. Includes answers and images.'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(project.event||'athlete-story').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Exported a copy of your story and photos.');}
async function attachPhotos(input){
 const momentId=input.dataset.upload;const files=Array.from(input.files||[]);let added=0;
 for(const file of files){
  if(project.media.length>=12){notify('This demo supports up to 12 photos. Remove one to add another.',true);break;}
  if(!/^image\/(jpeg|png|webp|gif|avif)$/.test(file.type)){notify(`${file.name}: please choose a JPG, PNG, WebP, GIF, or AVIF image.`,true);continue;}
  if(file.size>8*1024*1024){notify(`${file.name} is larger than 8 MB. Please choose a smaller image.`,true);continue;}
  const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read '+file.name));r.readAsDataURL(file);});
  project.media.push({id:uid(),momentId,filename:file.name,type:file.type,dataUrl});added++;
 }
 if(added){dirty();await persist();notify(`${added} ${added===1?'photo added':'photos added'} to this moment.`);}await render();
}

// Synchronize editor controls before any asynchronous save or render. `change`
// alone is insufficient when an approval click follows an edit immediately.
function synchronizeEditor(el){
 if(!project)return false;
 if(el.dataset.answerEdit){const changed=updateAnswer(project,el.dataset.answerEdit,el.value);if(changed)dirty();return changed;}
 if(el.dataset.projectEdit){const key=el.dataset.projectEdit;if(project[key]===el.value)return false;project[key]=el.value;if(project.seedKey==='alex'&&['event','activity'].includes(key)){project.showSeedGeography=false;notify('STP demo locations hidden for your changed event. You can add your own locations in moment review.');}dirty();return true;}
 if(el.dataset.edit||el.dataset.context){
  const key=el.dataset.edit||el.dataset.context;
  let value=el.value;
  if(['latitude','longitude'].includes(key)){value=el.value.trim()===''?undefined:Number(el.value);if(value!==undefined&&(!Number.isFinite(value)||Math.abs(value)>(key==='latitude'?90:180))){el.setCustomValidity('Enter a valid coordinate or leave blank.');el.reportValidity();return false;}el.setCustomValidity('');}
  const m=project.moments.find(x=>x.id===el.dataset.id);
  if(!m||m[key]===value||(el.dataset.context&&!m[key]&&!value))return false;
  m[key]=value;if(['latitude','longitude'].includes(key))m.locationProvenance='athlete_added';m.approved=false;if(el.dataset.edit)m.edited=true;else m.contextEdited=true;m.revision=(m.revision||1)+1;dirty();
  const card=el.closest('.moment-card');
  if(card){const badge=card.querySelector('.badge');badge.textContent='Draft · review needed';badge.classList.remove('approved');const approval=card.querySelector('[data-action="approve-moment"]');approval.disabled=!!project.needsRegeneration;approval.textContent='Approve moment';approval.classList.remove('secondary');}
  document.querySelectorAll('[data-action="stage"][data-stage="media"],[data-action="stage"][data-stage="preview"]').forEach(b=>b.setAttribute('disabled',''));
  const count=document.querySelector('.review-tools .badge');if(count)count.textContent=`${project.moments.filter(x=>x.approved).length} / ${project.moments.length} approved`;
  return true;
 }
 if(el.dataset.metric){
  const raw=el.value.trim(),value=Number(raw),key=el.dataset.metric;
  if(raw&&(!Number.isFinite(value)||value<0||value>1000000))return false;
  project.metrics||={};
  if(raw?project.metrics[key]===value:!(key in project.metrics))return false;
  if(raw)project.metrics[key]=value;else delete project.metrics[key];
  project.metrics.source='athlete_reported';delete project.metrics.weekly;delete project.metrics.sourceTurnIds;project.metrics.manuallyEdited=true;dirty();return true;
 }
 return false;
}
function scheduleEditorSave(){clearTimeout(editSaveTimer);saveState='Unsaved changes';updateSaveLabel();editSaveTimer=setTimeout(()=>{editSaveTimer=null;persist();},350);}
async function flushEditor(){
 let changed=false;
 app.querySelectorAll('[data-edit],[data-metric],[data-context],[data-answer-edit],[data-project-edit]').forEach(el=>{if(synchronizeEditor(el))changed=true;});
 if(changed||editSaveTimer!==null){clearTimeout(editSaveTimer);editSaveTimer=null;await persist();}
}
app.addEventListener('input',event=>{
 if(event.target.id==='answer')document.querySelector('#character-count').textContent=`${event.target.value.length.toLocaleString()} / 8,000`;
 if(synchronizeEditor(event.target))scheduleEditorSave();
});
app.addEventListener('change',async event=>{
 const el=event.target;
 try{
  if(el.dataset.edit||el.dataset.metric||el.dataset.context||el.dataset.answerEdit||el.dataset.projectEdit){synchronizeEditor(el);clearTimeout(editSaveTimer);editSaveTimer=null;await persist();}
  if(el.dataset.answerUse){const t=project.turns.find(t=>t.id===el.dataset.answerUse);if(t&&updateAnswer(project,t.id,t.answer,el.checked?'include':'conversation_only')){dirty();await persist();}}
  if(el.dataset.upload){busy=true;try{await attachPhotos(el);}finally{busy=false;}}
  if(el.dataset.tag){const a=project.media.find(a=>a.id===el.dataset.tag);if(a){a.momentId=el.value;dirty();await persist();await render();}}
 }catch(e){notify(e.message,true);}
});
app.addEventListener('submit',async event=>{
 event.preventDefault();if(busy)return;busy=true;
 try{
  if(event.target.id==='setup-form'){
   const f=new FormData(event.target),name=String(f.get('name')).trim(),experience=String(f.get('event')).trim();if(!name||!experience){notify('Add your name and event to begin.',true);return;}
   project={id:uid(),revision:1,name,event:experience,activity:String(f.get('activity')),date:String(f.get('date')||''),why:String(f.get('why')||'').trim(),turns:[],moments:[],media:[],metrics:{source:'athlete_reported'},stage:'interview',finalApproved:false,createdAt:new Date().toISOString()};error='';await setStage('interview');
  }
  if(event.target.id==='answer-form'){
   const q=getNextQuestion(project),answer=String(new FormData(event.target).get('answer')||'').trim();if(!answer){notify('Add an answer, or choose Skip.');return;}
   project.turns.push({id:uid(),questionId:q.id,question:q.text,answer,createdAt:new Date().toISOString()});if(project.moments.length){project.needsRegeneration=true;project.moments.forEach(m=>m.approved=false);}dirty();await persist();await render({focus:true});
  }
 }catch(e){notify(e.message,true);}finally{busy=false;}
});
document.addEventListener('click',event=>{
 const choice=event.target.closest('[data-story-select]');
 if(choice&&project){selectedMoment=choice.dataset.storySelect;render();return;}
 const photo=event.target.closest('[data-story-photo]');
 if(photo&&project){const asset=photo.dataset.storyPhoto==='overview-photo'?{dataUrl:project.overviewPhoto,filename:project.name+' · overview image'}:project.media.find(a=>a.id===photo.dataset.storyPhoto);if(!asset||!safeImage(asset.dataUrl))return;const dialog=document.querySelector('#photo-dialog');dialog.innerHTML=`<div class="dialog-head"><span>${esc(asset.filename)}</span><button class="icon-button" data-close-photo aria-label="Close photo">✕</button></div><img src="${esc(safeImage(asset.dataUrl))}" alt="${esc(asset.filename)}">`;dialog.showModal();}
 if(event.target.closest('[data-close-photo]'))document.querySelector('#photo-dialog').close();
});
document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-action]');if(!button||button.disabled)return;event.preventDefault();const action=button.dataset.action;
 if(action==='about'){document.querySelector('#about-dialog').showModal();return;}
 if(action==='close-about'){document.querySelector('#about-dialog').close();return;}
 if(busy)return;busy=true;
 try{
  if(project&&['review','interview'].includes(screen))await flushEditor();
  if(action==='seed'){selectedMoment='overview';project=cleanProject(await loadSeed(button.dataset.seed,button.dataset.stage));screen=project.stage;error='';await persist();await render({focus:true});}
  if(action==='edit-answers'){project.editInterview=true;await setStage('interview');}
  if(action==='cancel-update'){delete project.pendingMomentUpdate;await persist();await render();}
  if(action==='apply-update'){project.momentHistory||=[];project.momentHistory.push({moments:structuredClone(project.moments),answersBefore:structuredClone(project.sourceChanges||{}),at:new Date().toISOString()});project.moments=project.pendingMomentUpdate;delete project.pendingMomentUpdate;project.needsRegeneration=false;project.sourceChanges={};if(!project.metrics?.manuallyEdited&&project.metrics?.source!=='synthetic_fixture')project.metrics=extractTrainingMetrics(project);dirty();await persist();await render();}
  if(action==='home'){screen='home';project=null;await render({focus:true});}
  if(action==='new'){screen='setup';project=null;error='';await render({focus:true});}
  if(action==='sample'){selectedMoment='overview';project=cleanProject(createExample(button.dataset.kind));project.sample=true;project.stage='preview';project.moments.forEach(m=>m.approved=true);project.finalApproved=false;screen='preview';error='';await persist();await render({focus:true});}
  if(action==='resume'){selectedMoment='overview';project=cleanProject(await loadProject(button.dataset.id));screen=project.stage||'review';error='';await render({focus:true});}
  if(action==='delete-project'){if(confirm('Delete this story and its photos from this browser? Export it first if you want to keep a copy.')){await deleteProject(button.dataset.id);await renderHome();}}
  if(action==='retry-save'){error='';await persist();await render();}
  if(action==='stage')await setStage(button.dataset.stage);
  if(action==='generate')await generate();
  if(action==='skip'){const q=getNextQuestion(project);if(q){project.turns.push({id:uid(),questionId:q.id,question:q.text,answer:'',createdAt:new Date().toISOString()});dirty();await persist();await render({focus:true});}}
  if(action==='approve-moment'){if(project.needsRegeneration){notify('Update moments from your new answers before approving.',true);return;}const m=project.moments.find(m=>m.id===button.dataset.id);if(!m.title.trim()||!m.text.trim()){notify('A moment needs a heading and text before approval.',true);return;}m.approved=true;m.approvalOrigin='user';dirty();await persist();await render();}
  if(action==='approve-all'){if(project.needsRegeneration){notify('Update moments from your new answers before approving.',true);return;}if(project.moments.some(m=>!m.title.trim()||!m.text.trim())){notify('Every moment needs a heading and text before approval.',true);return;}project.moments.forEach(m=>{m.approved=true;m.approvalOrigin='user';});dirty();await persist();await render();notify('Moments approved. You can add photos next.');}
  if(action==='remove-moment'){if(confirm('Remove this moment from your story? Its interview answers will remain saved.')){project.moments=project.moments.filter(m=>m.id!==button.dataset.id);project.media=project.media.filter(a=>a.momentId!==button.dataset.id);dirty();await persist();await render();}}
  if(action==='move-up'||action==='move-down'){const i=project.moments.findIndex(m=>m.id===button.dataset.id),j=i+(action==='move-up'?-1:1);if(j>=0&&j<project.moments.length){[project.moments[i],project.moments[j]]=[project.moments[j],project.moments[i]];dirty();await persist();await render();}}
  if(action==='remove-media'){project.media=project.media.filter(a=>a.id!==button.dataset.id);dirty();await persist();await render();}
  if(action==='final-approve'){if(project.needsRegeneration||!project.moments.length||project.moments.some(m=>!m.approved)){notify('Review your draft moments first.',true);return;}project.finalApproved=true;project.approvedRevision=project.revision;project.approvedAt=new Date().toISOString();const saved=await persist();await render();if(saved)notify('This version is approved and saved in this browser.');}
  if(action==='overview-photo'){const asset=project.media.find(a=>a.id===button.dataset.id);if(asset){project.overviewPhoto=asset.dataUrl;dirty();await persist();notify('Overview image updated.');}}
  if(action==='export')exportProject();
 }catch(e){notify(e.message,true);}finally{busy=false;}
});
window.addEventListener('unhandledrejection',event=>{notify('Something did not finish. Your existing saved stories are still available. '+(event.reason?.message||''),true);});
render();
